import '../AboutMeEdit/AboutMeEdit.css'
import { useDispatch } from 'react-redux'
import { editedProfile, updateUserProfile } from '../../../../../store/slices/UserSlice'

export default function AboutMeEdit() {

  const profile = JSON.parse(localStorage.getItem("userProfile"))
  console.log(profile);

  const handlerSubmit = async (e) => {
    const dispatch = useDispatch
    const token = localStorage.getItem("token")
        e.preventDefault()
        const [FirstName,LastName,Age,Bio,Location,Profession,Hobbies] = e.target
        const newUser = {
          id: profile.id,
          first_name: FirstName.value,
          last_name: LastName.value,
          age: Age.value,
          bio: Bio.value,
          location: Location.value,
          profession: Profession.value,
          hobbies: Hobbies.value,
          image: profile.image,
          gender: profile.gender,
          login: profile.login,
          friend_request: profile.friend_request,
          friend_list: profile.friend_list,
          photo: profile.photo,
        }
        await fetch(`http://localhost:8000/api/users/${profile.id}`, {
          method: 'PATCH',
          body: JSON.stringify(newUser),
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`,
            Accept: 'application/json'

          },

        })
        dispatch(updateUserProfile(newUser))
        e.target.reset()

      }
  return (
    <div className='form-container' >
                    <form onSubmit={(e) => handlerSubmit(e)} >
                    <label>FirstName:</label>
                    <input type="text"  />
                    <label>LastName:</label>
                    <input type="text"  />
                    <label>Age:</label>
                    <input 
                    type="text"
                    onKeyDown={(e) => {
                      if(!/[0-9]/.test(e.key) && (e.key !== "Backspace" && e.key !== "Tab")) {
                        e.preventDefault();
                      }
                    }} 

                    />
                    <label>Bio:</label>
                    <input type="text"  />
                    <label>Location:</label>
                    <input type="text"  />
                    <label>Profesion:</label>
                    <input type="text"  />
                    <label>Hobbie:</label>
                    <input type="text" />
                    <button>Save</button>
                    </form>
                  </div>
  )
}
